edits.new_string:
# ---- cart ----
c = Cart().add("kb-01").add("ms-02", 2)
assert c.count() == 3
assert c.subtotal() == 657.0

# 库存：超库存抛 ValueError
for sku, qty in (("mn-03", 6), ("cb-05", 51)):   # 显示器库存 5，数据线库存 50
    try:
        Cart().add(sku, qty)
    except ValueError:
        pass
    else:
        raise AssertionError(f"加购 {qty} 件 {sku} 超过库存应当抛 ValueError")
# 恰好等于库存：允许
try:
    Cart().add("mn-03", 5)
except ValueError:
    raise AssertionError("加购恰好等于库存应当允许")
# 同一 SKU 分多次加购的累计数量同样受限：10 + 5 > kb-01 库存 12
c2 = Cart()
for qty in (10, 5):
    try:
        c2.add("kb-01", qty)
    except ValueError:
        pass
    else:
        if qty == 10:
            continue
        raise AssertionError("累计加购超过库存应当抛 ValueError")

# ---- report ----
text = summarize(Cart().add("mn-03"))
assert "订单明细" in text and "显示器" in text and "应付" in text
assert "库存" in text
